#define CITY_NAME_MAX_LEN      96
#define CITY_COUNTRY_MAX_LEN   96
#define CITY_TZ_MAX_LEN        64

typedef struct {
    char city[CITY_NAME_MAX_LEN];
    char country[CITY_COUNTRY_MAX_LEN];
    char tz_string[CITY_TZ_MAX_LEN];
} city_t;

/* Built-in cities. User-added cities are stored after this list in NVS. */
