#define DEFAULT_CITY_COUNT (sizeof(default_cities) / sizeof(default_cities[0]))
static city_t cities[MAX_CITIES];
static uint8_t city_count = 0;
#define CITY_COUNT (city_count)
static uint8_t current_city_index = 0;
static volatile bool need_tz_update = false;
static volatile bool city_state_save_pending = false;

static QueueHandle_t button_evt_queue = NULL;
static SemaphoreHandle_t i2c_mutex = NULL;

static void init_cities(void)
{
    city_count = 0;
    for (size_t i = 0; i < DEFAULT_CITY_COUNT && i < MAX_CITIES; i++) {
        cities[city_count++] = default_cities[i];
    }

    nvs_handle_t handle;
    if (nvs_open("clock", NVS_READONLY, &handle) != ESP_OK) return;

    uint8_t custom_count = 0;
    nvs_get_u8(handle, "city_custom_count", &custom_count);
    if (custom_count > MAX_CITIES - DEFAULT_CITY_COUNT) {
        custom_count = MAX_CITIES - DEFAULT_CITY_COUNT;
    }

    for (uint8_t i = 0; i < custom_count; i++) {
        city_t item = {0};
        char key[20];
        size_t size;

        snprintf(key, sizeof(key), "city_name_%u", (unsigned)i);
        size = sizeof(item.city);
        if (nvs_get_str(handle, key, item.city, &size) != ESP_OK) continue;
        snprintf(key, sizeof(key), "city_country_%u", (unsigned)i);
        size = sizeof(item.country);
        if (nvs_get_str(handle, key, item.country, &size) != ESP_OK) continue;
        snprintf(key, sizeof(key), "city_tz_%u", (unsigned)i);
        size = sizeof(item.tz_string);
        if (nvs_get_str(handle, key, item.tz_string, &size) != ESP_OK) continue;

        cities[city_count++] = item;
    }
    nvs_close(handle);
}

static void save_custom_cities(void)
{
    nvs_handle_t handle;
    if (nvs_open("clock", NVS_READWRITE, &handle) != ESP_OK) return;

    uint8_t custom_count = city_count > DEFAULT_CITY_COUNT
        ? city_count - DEFAULT_CITY_COUNT : 0;
    nvs_set_u8(handle, "city_custom_count", custom_count);

    for (uint8_t i = 0; i < MAX_CITIES - DEFAULT_CITY_COUNT; i++) {
        char key[20];
        if (i < custom_count) {
            const city_t *item = &cities[DEFAULT_CITY_COUNT + i];
            snprintf(key, sizeof(key), "city_name_%u", (unsigned)i);
            nvs_set_str(handle, key, item->city);
            snprintf(key, sizeof(key), "city_country_%u", (unsigned)i);
            nvs_set_str(handle, key, item->country);
            snprintf(key, sizeof(key), "city_tz_%u", (unsigned)i);
            nvs_set_str(handle, key, item->tz_string);
        } else {
            snprintf(key, sizeof(key), "city_name_%u", (unsigned)i);
            nvs_erase_key(handle, key);
            snprintf(key, sizeof(key), "city_country_%u", (unsigned)i);
            nvs_erase_key(handle, key);
            snprintf(key, sizeof(key), "city_tz_%u", (unsigned)i);
            nvs_erase_key(handle, key);
        }
    }
    nvs_commit(handle);
    nvs_close(handle);
}

static void load_current_city(void)
{
    nvs_handle_t handle;
    uint8_t saved = 0;
    if (nvs_open("clock", NVS_READONLY, &handle) == ESP_OK) {
        if (nvs_get_u8(handle, "city_index", &saved) == ESP_OK && saved < CITY_COUNT) {
            current_city_index = saved;
        }
        nvs_close(handle);
    }
}

static void save_current_city(void)
{
    nvs_handle_t handle;
    if (nvs_open("clock", NVS_READWRITE, &handle) == ESP_OK) {
        nvs_set_u8(handle, "city_index", current_city_index);
        nvs_commit(handle);
        nvs_close(handle);
    }
}

static void save_sync_metadata(void);

static void load_ntp_config(void)
{
    ntp_cfg_count = (uint8_t)(sizeof(ntp_default_servers) / sizeof(ntp_default_servers[0]));
    if (ntp_cfg_count > MAX_NTP_SERVERS) ntp_cfg_count = MAX_NTP_SERVERS;
    ntp_timeout_ms = NTP_TIMEOUT_DEFAULT_MS;
    sync_interval_sec = SYNC_INTERVAL_DEFAULT_SEC;

    for (uint8_t i = 0; i < ntp_cfg_count; i++) {
        strlcpy(ntp_cfg[i].host, ntp_default_servers[i], sizeof(ntp_cfg[i].host));
        ntp_cfg[i].enabled = true;
    }

    nvs_handle_t handle;
    if (nvs_open("clock", NVS_READONLY, &handle) != ESP_OK) return;

    uint8_t saved_count = 0;
    if (nvs_get_u8(handle, "ntp_count", &saved_count) == ESP_OK &&
        saved_count > 0 && saved_count <= MAX_NTP_SERVERS) {
        ntp_cfg_count = saved_count;
    }

    uint32_t value;
    if (nvs_get_u32(handle, "ntp_timeout", &value) == ESP_OK && value >= 1000 && value <= 120000) {
        ntp_timeout_ms = value;
    }
    if (nvs_get_u32(handle, "ntp_interval", &value) == ESP_OK && value >= 60 && value <= 7U * 24U * 3600U) {
        sync_interval_sec = value;
    }

    for (uint8_t i = 0; i < ntp_cfg_count; i++) {
        char key[16];
        size_t length = sizeof(ntp_cfg[i].host);
        snprintf(key, sizeof(key), "ntp_host_%u", (unsigned)i);
        if (nvs_get_str(handle, key, ntp_cfg[i].host, &length) != ESP_OK ||
            ntp_cfg[i].host[0] == '\0') {
            /* Missing custom entries fall back safely, including indexes above the default list. */
            const size_t default_count = sizeof(ntp_default_servers) / sizeof(ntp_default_servers[0]);
            const char *fallback = i < default_count ? ntp_default_servers[i] : CONFIG_CLOCK_NTP_SERVER;
            strlcpy(ntp_cfg[i].host, fallback, sizeof(ntp_cfg[i].host));
            ntp_cfg[i].enabled = true;
        }

        uint8_t enabled = 1;
        snprintf(key, sizeof(key), "ntp_en_%u", (unsigned)i);
        if (nvs_get_u8(handle, key, &enabled) == ESP_OK) {
            ntp_cfg[i].enabled = enabled != 0;
        }
    }

    int64_t saved_last_sync = 0;
    uint8_t saved_manual = 0;
    nvs_get_i64(handle, "last_sync", &saved_last_sync);
    nvs_get_u8(handle, "last_manual", &saved_manual);
    if (saved_last_sync > 0) {
        last_sync_epoch = (time_t)saved_last_sync;
        next_sync_epoch = last_sync_epoch + (time_t)sync_interval_sec;
    }
    last_sync_manual = saved_manual != 0;

    nvs_close(handle);
}

static void save_sync_metadata(void)
{
    nvs_handle_t handle;
    if (nvs_open("clock", NVS_READWRITE, &handle) != ESP_OK) return;
    nvs_set_i64(handle, "last_sync", (int64_t)last_sync_epoch);
    nvs_set_u8(handle, "last_manual", last_sync_manual ? 1 : 0);
    nvs_commit(handle);
    nvs_close(handle);
}

static void save_ntp_config(void)
{
    nvs_handle_t handle;
    if (nvs_open("clock", NVS_READWRITE, &handle) != ESP_OK) return;

    nvs_set_u8(handle, "ntp_count", ntp_cfg_count);
    nvs_set_u32(handle, "ntp_timeout", ntp_timeout_ms);
    nvs_set_u32(handle, "ntp_interval", sync_interval_sec);

    for (uint8_t i = 0; i < MAX_NTP_SERVERS; i++) {
        char key[16];
        if (i < ntp_cfg_count && ntp_cfg[i].host[0] != '\0') {
            snprintf(key, sizeof(key), "ntp_host_%u", (unsigned)i);
            nvs_set_str(handle, key, ntp_cfg[i].host);
            snprintf(key, sizeof(key), "ntp_en_%u", (unsigned)i);
            nvs_set_u8(handle, key, ntp_cfg[i].enabled ? 1 : 0);
        } else {
            snprintf(key, sizeof(key), "ntp_host_%u", (unsigned)i);
            nvs_erase_key(handle, key);
            snprintf(key, sizeof(key), "ntp_en_%u", (unsigned)i);
            nvs_erase_key(handle, key);
        }
    }
    nvs_commit(handle);
    nvs_close(handle);
}

static void load_alarms(void)
{
    memset(alarms, 0, sizeof(alarms));
    for (uint8_t i = 0; i < MAX_ALARMS; i++) alarm_last_key[i] = -1;
    alarm_count = 0;

    nvs_handle_t handle;
    if (nvs_open("clock", NVS_READONLY, &handle) != ESP_OK) return;

    uint8_t saved_count = 0;
    size_t size = sizeof(alarms);
    if (nvs_get_u8(handle, "alarm_count", &saved_count) == ESP_OK &&
        saved_count <= MAX_ALARMS &&
        nvs_get_blob(handle, "alarms", alarms, &size) == ESP_OK &&
        size == sizeof(alarms)) {
        alarm_count = saved_count;
    }
    nvs_close(handle);
}

static void save_alarms(void)
{
    nvs_handle_t handle;
    if (nvs_open("clock", NVS_READWRITE, &handle) != ESP_OK) return;
    nvs_set_u8(handle, "alarm_count", alarm_count);
    nvs_set_blob(handle, "alarms", alarms, sizeof(alarms));
    nvs_commit(handle);
    nvs_close(handle);
}

// ================================================
//  ПРОТОТИП функции обратного вызова NTP
// ================================================
static void time_sync_notification_cb(struct timeval *tv);

// ================================================
//  ДРАЙВЕР DS3231
// ================================================

static esp_err_t ds3231_read_bytes(uint8_t reg, uint8_t *buf, size_t len)
{
    if (!buf || len == 0) return ESP_ERR_INVALID_ARG;
    if (!i2c_mutex || xSemaphoreTake(i2c_mutex, pdMS_TO_TICKS(150)) != pdTRUE) {
        return ESP_ERR_TIMEOUT;
    }

    i2c_cmd_handle_t cmd = i2c_cmd_link_create();
    if (!cmd) {
        xSemaphoreGive(i2c_mutex);
        return ESP_ERR_NO_MEM;
    }
    i2c_master_start(cmd);
    i2c_master_write_byte(cmd, (0x68 << 1) | I2C_MASTER_WRITE, true);
    i2c_master_write_byte(cmd, reg, true);
    i2c_master_start(cmd);
    i2c_master_write_byte(cmd, (0x68 << 1) | I2C_MASTER_READ, true);
    i2c_master_read(cmd, buf, len, I2C_MASTER_LAST_NACK);
    i2c_master_stop(cmd);
    const esp_err_t ret = i2c_master_cmd_begin(I2C_MASTER_NUM, cmd, pdMS_TO_TICKS(100));
    i2c_cmd_link_delete(cmd);
    xSemaphoreGive(i2c_mutex);
    return ret;
}

static uint8_t bcd2bin(uint8_t bcd)
{
    return ((bcd >> 4) & 0x0F) * 10 + (bcd & 0x0F);
}

static uint8_t bin2bcd(uint8_t bin)
{
    return ((bin / 10) << 4) | (bin % 10);
}

static bool ds3231_check(void)
{
    uint8_t reg;
    esp_err_t ret = ds3231_read_bytes(0x00, &reg, 1);
    if (ret != ESP_OK) return false;
    return ((reg & 0x7F) <= 0x59);
}

static bool ds3231_read_time(struct tm *timeinfo)
{
    if (!timeinfo) return false;

    uint8_t buf[7];
    if (ds3231_read_bytes(0x00, buf, sizeof(buf)) != ESP_OK) return false;

    struct tm result = { .tm_isdst = -1 };
    result.tm_sec = bcd2bin(buf[0] & 0x7F);
    result.tm_min = bcd2bin(buf[1] & 0x7F);

    const uint8_t hour_reg = buf[2];
    if (hour_reg & 0x40) {
        const uint8_t hour = bcd2bin(hour_reg & 0x1F);
        result.tm_hour = (hour % 12) + ((hour_reg & 0x20) ? 12 : 0);
    } else {
        result.tm_hour = bcd2bin(hour_reg & 0x3F);
    }

    result.tm_wday = (bcd2bin(buf[3] & 0x07) + 6) % 7;
    result.tm_mday = bcd2bin(buf[4] & 0x3F);
    result.tm_mon = bcd2bin(buf[5] & 0x1F) - 1;
    result.tm_year = bcd2bin(buf[6]) + 100;

    if (result.tm_sec > 59 || result.tm_min > 59 || result.tm_hour > 23 ||
        result.tm_mday < 1 || result.tm_mday > 31 ||
        result.tm_mon < 0 || result.tm_mon > 11) {
        return false;
    }

    *timeinfo = result;
    return true;
}

static bool ds3231_write_time(const struct tm *timeinfo)
{
    if (!timeinfo || timeinfo->tm_year < 100 || timeinfo->tm_year > 199 ||
        timeinfo->tm_mon < 0 || timeinfo->tm_mon > 11 ||
        timeinfo->tm_mday < 1 || timeinfo->tm_mday > 31) {
        return false;
    }

    if (!i2c_mutex || xSemaphoreTake(i2c_mutex, pdMS_TO_TICKS(150)) != pdTRUE) {
        return false;
    }

    // Write the complete register block in one I2C transaction instead of seven.
    const uint8_t values[7] = {
        bin2bcd((uint8_t)timeinfo->tm_sec),
        bin2bcd((uint8_t)timeinfo->tm_min),
        bin2bcd((uint8_t)timeinfo->tm_hour),
        (uint8_t)(timeinfo->tm_wday + 1),
        bin2bcd((uint8_t)timeinfo->tm_mday),
        bin2bcd((uint8_t)(timeinfo->tm_mon + 1)),
        bin2bcd((uint8_t)(timeinfo->tm_year % 100)),
    };

    i2c_cmd_handle_t cmd = i2c_cmd_link_create();
    if (!cmd) {
        xSemaphoreGive(i2c_mutex);
        return false;
    }
    i2c_master_start(cmd);
    i2c_master_write_byte(cmd, (0x68 << 1) | I2C_MASTER_WRITE, true);
    i2c_master_write_byte(cmd, 0x00, true);
    i2c_master_write(cmd, (uint8_t *)values, sizeof(values), true);
    i2c_master_stop(cmd);
    const esp_err_t err = i2c_master_cmd_begin(I2C_MASTER_NUM, cmd, pdMS_TO_TICKS(100));
    i2c_cmd_link_delete(cmd);
    xSemaphoreGive(i2c_mutex);
    return err == ESP_OK;
}

static void update_rtc_from_system_time(void)
{
    if (!rtc_available) return;

    time_t now;
    time(&now);
    struct tm local_time;
    localtime_r(&now, &local_time);
    if (!ds3231_write_time(&local_time)) {
        ESP_LOGW(TAG, "Failed to update RTC after timezone change");
    }
}

static void i2c_master_init(void)
{
    i2c_mutex = xSemaphoreCreateMutex();
    ESP_ERROR_CHECK(i2c_mutex ? ESP_OK : ESP_ERR_NO_MEM);

    i2c_config_t conf = {
        .mode = I2C_MODE_MASTER,
        .sda_io_num = I2C_MASTER_SDA_IO,
        .scl_io_num = I2C_MASTER_SCL_IO,
        .sda_pullup_en = GPIO_PULLUP_ENABLE,
        .scl_pullup_en = GPIO_PULLUP_ENABLE,
        .master.clk_speed = I2C_MASTER_FREQ_HZ,
    };

    ESP_ERROR_CHECK(i2c_param_config(I2C_MASTER_NUM, &conf));
    ESP_ERROR_CHECK(i2c_driver_install(I2C_MASTER_NUM, conf.mode, 0, 0, 0));
    vTaskDelay(pdMS_TO_TICKS(50));
}


// ================================================
//  NTP
// ================================================
static bool sync_with_ntp_server(const char *server, int timeout_ms)
{
    esp_sntp_stop();
    ntp_synced = false;
    esp_sntp_setoperatingmode(SNTP_OPMODE_POLL);
    esp_sntp_setservername(0, server);
    esp_sntp_set_time_sync_notification_cb(time_sync_notification_cb);
    esp_sntp_init();

    int wait_ms = 0;
    while (!ntp_synced && wait_ms < timeout_ms) {
        vTaskDelay(pdMS_TO_TICKS(100));
        wait_ms += 100;
    }
    return ntp_synced;
}

static bool sync_time_with_ntp(bool manual_sync)
{
    bool synced = false;
    bool has_enabled_server = false;

    for (uint8_t i = 0; i < ntp_cfg_count; i++) {
        if (!ntp_cfg[i].enabled || ntp_cfg[i].host[0] == '\0') continue;
        has_enabled_server = true;
        ESP_LOGI(TAG, "Trying NTP server: %s", ntp_cfg[i].host);
        if (sync_with_ntp_server(ntp_cfg[i].host, (int)ntp_timeout_ms)) {
            ESP_LOGI(TAG, "Synchronized with %s", ntp_cfg[i].host);
            synced = true;
            break;
        }
        vTaskDelay(pdMS_TO_TICKS(500));
    }

    if (!has_enabled_server) {
        ESP_LOGE(TAG, "No enabled NTP servers configured.");
    }
    if (!synced) {
        ESP_LOGE(TAG, "All enabled NTP servers failed.");
        ntp_synced = false;
        return false;
    }

    time_t now;
    time(&now);
    ntp_synced = true;
    last_sync_epoch = now;
    next_sync_epoch = now + (time_t)sync_interval_sec;
    last_sync_manual = manual_sync;
    save_sync_metadata();

    if (rtc_available) {
        struct tm timeinfo;
        localtime_r(&now, &timeinfo);
        if (ds3231_write_time(&timeinfo)) {
            ESP_LOGI(TAG, "RTC updated from NTP");
        } else {
            ESP_LOGE(TAG, "Failed to update RTC");
        }
    }
    return true;
}

static void start_background_ntp(void)
{
    esp_sntp_stop();
    esp_sntp_setoperatingmode(SNTP_OPMODE_POLL);

    int slot = 0;
    for (uint8_t i = 0; i < ntp_cfg_count && slot < 3; i++) {
        if (ntp_cfg[i].enabled && ntp_cfg[i].host[0] != '\0') {
            esp_sntp_setservername(slot++, ntp_cfg[i].host);
        }
    }
    if (slot == 0) {
        esp_sntp_setservername(0, "pool.ntp.org");
    }

    esp_sntp_set_time_sync_notification_cb(time_sync_notification_cb);
    esp_sntp_set_sync_interval(sync_interval_sec * 1000U);
    esp_sntp_init();

    if (next_sync_epoch == 0) {
        time_t now;
        time(&now);
        if (now > 0) next_sync_epoch = now + (time_t)sync_interval_sec;
    }
}

static void time_sync_notification_cb(struct timeval *tv)
{
    ntp_synced = true;
    // A manual sync records its own metadata after trying the configured servers.
    if (ntp_sync_running) return;

    ESP_LOGI(TAG, "Background NTP sync successful");
    last_sync_epoch = tv->tv_sec;
    next_sync_epoch = tv->tv_sec + (time_t)sync_interval_sec;
    last_sync_manual = false;
    save_sync_metadata();

    if (rtc_available) {
        time_t now = tv->tv_sec;
        struct tm timeinfo;
        localtime_r(&now, &timeinfo);
        if (ds3231_write_time(&timeinfo)) {
            ESP_LOGI(TAG, "RTC updated from NTP (background)");
        } else {
            ESP_LOGE(TAG, "Failed to update RTC (background)");
        }
    }
}

static void run_ntp_sync(bool manual_sync)
{
    if (ntp_sync_running) return;

    ntp_sync_running = true;
    const bool synced = sync_time_with_ntp(manual_sync);
    start_background_ntp();
    ntp_sync_running = false;

    ESP_LOGI(TAG, "%s NTP sync %s", manual_sync ? "Manual" : "Automatic",
             synced ? "successful" : "failed; background retries remain active");
}

static void force_ntp_sync(void)
{
    run_ntp_sync(true);
}

// ================================================
//  WIFI
// ================================================
static void schedule_wifi_reconnect(void)
{
    if (wifi_setup_mode || esp_timer_is_active(wifi_reconnect_timer)) return;

    uint32_t delay_sec = 1U << (wifi_retry_count < 5 ? wifi_retry_count : 5);
    if (delay_sec > 30) delay_sec = 30;
    if (wifi_retry_count < UINT32_MAX) wifi_retry_count++;

    ESP_LOGI(TAG, "Wi-Fi reconnect in %lu seconds", (unsigned long)delay_sec);
    esp_timer_start_once(wifi_reconnect_timer, (uint64_t)delay_sec * 1000000ULL);
}

static void wifi_reconnect_cb(void *arg)
{
    (void)arg;
    if (!wifi_setup_mode && esp_wifi_connect() != ESP_OK) schedule_wifi_reconnect();
}

static void captive_dns_task(void *arg)
{
    (void)arg;
    const int sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_IP);
    if (sock < 0) {
        ESP_LOGE(TAG, "Cannot create captive portal DNS socket");
        vTaskDelete(NULL);
        return;
    }

    struct sockaddr_in listen_addr = {
        .sin_family = AF_INET,
        .sin_port = PP_HTONS(53),
        .sin_addr.s_addr = PP_HTONL(INADDR_ANY),
    };
    if (bind(sock, (struct sockaddr *)&listen_addr, sizeof(listen_addr)) != 0) {
        ESP_LOGE(TAG, "Cannot bind captive portal DNS socket");
        close(sock);
        vTaskDelete(NULL);
        return;
    }

    uint8_t packet[512];
    for (;;) {
        struct sockaddr_in source_addr;
        socklen_t source_len = sizeof(source_addr);
        const int received = recvfrom(sock, packet, sizeof(packet) - 16, 0,
                                      (struct sockaddr *)&source_addr, &source_len);
        if (received < 12) continue;
        if ((packet[2] & 0x80) != 0 || packet[4] != 0 || packet[5] != 1) continue;

        size_t pos = 12;
        while (pos < (size_t)received) {
            const uint8_t label_len = packet[pos++];
            if (label_len == 0) break;
            if ((label_len & 0xC0) == 0xC0) {
                if (pos < (size_t)received) pos++;
                break;
            }
            if (label_len > 63 || pos + label_len >= (size_t)received) {
                pos = (size_t)received;
                break;
            }
            pos += label_len;
        }
        if (pos + 4 > (size_t)received) continue;

        const size_t question_end = pos + 4;
        const bool is_ipv4_query = packet[question_end - 4] == 0 && packet[question_end - 3] == 1;
        const size_t response_len = question_end + (is_ipv4_query ? 16 : 0);
        packet[2] = 0x81;
        packet[3] = 0x80;
        packet[6] = 0;
        packet[7] = is_ipv4_query ? 1 : 0;
        packet[8] = packet[9] = packet[10] = packet[11] = 0;
        if (is_ipv4_query) {
            const uint8_t answer[] = {
                0xC0, 0x0C,             /* Name: the question name */
                0x00, 0x01,             /* Type A */
                0x00, 0x01,             /* Class IN */
                0x00, 0x00, 0x00, 0x3C, /* TTL: 60 seconds */
                0x00, 0x04,             /* IPv4 address length */
                192, 168, 4, 1,
            };
            memcpy(packet + question_end, answer, sizeof(answer));
        }
        sendto(sock, packet, response_len, 0,
               (struct sockaddr *)&source_addr, source_len);
    }
}

static void start_wifi_setup(void)
{
    if (wifi_setup_mode) return;
    wifi_setup_mode = true;
    xEventGroupClearBits(wifi_event_group, WIFI_CONNECTED_BIT);
    if (esp_timer_is_active(wifi_reconnect_timer)) esp_timer_stop(wifi_reconnect_timer);
    esp_wifi_stop();

    wifi_config_t ap_config = {
        .ap = {
            .ssid = "Connecting the clock to Wi-Fi",
            .ssid_len = strlen("Connecting the clock to Wi-Fi"),
            .max_connection = 4,
            .authmode = WIFI_AUTH_OPEN,
        },
    };
    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_AP));
    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_AP, &ap_config));
    ESP_ERROR_CHECK(esp_wifi_start());
    if (xTaskCreate(captive_dns_task, "captive_dns", 3072, NULL, 3, NULL) != pdPASS) {
        ESP_LOGE(TAG, "Cannot start captive portal DNS; open http://192.168.4.1 manually");
    }
    ESP_LOGI(TAG, "Wi-Fi setup: connect to Connecting the clock to Wi-Fi; the setup page opens automatically");
}

static void wifi_setup_cb(void *arg)
{
    (void)arg;
    ESP_LOGW(TAG, "Wi-Fi connection was not established; opening simple setup");
    start_wifi_setup();
}

static void wifi_event_handler(void *arg, esp_event_base_t event_base,
                               int32_t event_id, void *event_data)
{
    (void)arg;

    if (event_base == WIFI_EVENT && event_id == WIFI_EVENT_STA_START) {
        wifi_retry_count = 0;
        if (esp_wifi_connect() != ESP_OK) schedule_wifi_reconnect();
        if (!esp_timer_is_active(wifi_setup_timer)) {
            esp_timer_start_once(wifi_setup_timer, 45000000ULL);
        }
    } else if (event_base == WIFI_EVENT && event_id == WIFI_EVENT_STA_DISCONNECTED) {
        xEventGroupClearBits(wifi_event_group, WIFI_CONNECTED_BIT);
        schedule_wifi_reconnect();
    } else if (event_base == IP_EVENT && event_id == IP_EVENT_STA_GOT_IP) {
        const ip_event_got_ip_t *event = (ip_event_got_ip_t *)event_data;
        wifi_retry_count = 0;
        if (esp_timer_is_active(wifi_reconnect_timer)) esp_timer_stop(wifi_reconnect_timer);
        if (esp_timer_is_active(wifi_setup_timer)) esp_timer_stop(wifi_setup_timer);
        ESP_LOGI(TAG, "Got IP: " IPSTR, IP2STR(&event->ip_info.ip));
        xEventGroupSetBits(wifi_event_group, WIFI_CONNECTED_BIT);
    }
}

static void load_wifi_config(void)
{
    strlcpy(wifi_ssid, WIFI_SSID, sizeof(wifi_ssid));
    strlcpy(wifi_password, WIFI_PASS, sizeof(wifi_password));

    nvs_handle_t handle;
    if (nvs_open("clock", NVS_READONLY, &handle) != ESP_OK) return;
    size_t length = sizeof(wifi_ssid);
    if (nvs_get_str(handle, "wifi_ssid", wifi_ssid, &length) != ESP_OK) {
        strlcpy(wifi_ssid, WIFI_SSID, sizeof(wifi_ssid));
    }
    length = sizeof(wifi_password);
    if (nvs_get_str(handle, "wifi_password", wifi_password, &length) != ESP_OK) {
        strlcpy(wifi_password, WIFI_PASS, sizeof(wifi_password));
    }
    nvs_close(handle);
}

static void wifi_init(void)
{
    wifi_event_group = xEventGroupCreate();

    esp_err_t nvs_ret = nvs_flash_init();
    if (nvs_ret == ESP_ERR_NVS_NO_FREE_PAGES || nvs_ret == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        ESP_ERROR_CHECK(nvs_flash_erase());
        nvs_ret = nvs_flash_init();
    }
    ESP_ERROR_CHECK(nvs_ret);
    load_wifi_config();

    ESP_ERROR_CHECK(esp_netif_init());
    ESP_ERROR_CHECK(esp_event_loop_create_default());
    ESP_ERROR_CHECK(esp_netif_create_default_wifi_sta() != NULL ? ESP_OK : ESP_FAIL);
    ESP_ERROR_CHECK(esp_netif_create_default_wifi_ap() != NULL ? ESP_OK : ESP_FAIL);

    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
    ESP_ERROR_CHECK(esp_wifi_init(&cfg));

    const esp_timer_create_args_t reconnect_args = {
        .callback = wifi_reconnect_cb,
        .name = "wifi_reconnect",
    };
    ESP_ERROR_CHECK(esp_timer_create(&reconnect_args, &wifi_reconnect_timer));
    const esp_timer_create_args_t setup_args = {
        .callback = wifi_setup_cb,
        .name = "wifi_setup",
    };
    ESP_ERROR_CHECK(esp_timer_create(&setup_args, &wifi_setup_timer));

    esp_event_handler_instance_t instance_any_id;
    esp_event_handler_instance_t instance_got_ip;
    ESP_ERROR_CHECK(esp_event_handler_instance_register(
        WIFI_EVENT, ESP_EVENT_ANY_ID, &wifi_event_handler, NULL, &instance_any_id));
    ESP_ERROR_CHECK(esp_event_handler_instance_register(
        IP_EVENT, IP_EVENT_STA_GOT_IP, &wifi_event_handler, NULL, &instance_got_ip));

    if (wifi_ssid[0] == '\0') {
        start_wifi_setup();
        return;
    }

    wifi_config_t wifi_config = {0};
    memcpy(wifi_config.sta.ssid, wifi_ssid, strnlen(wifi_ssid, sizeof(wifi_config.sta.ssid)));
    memcpy(wifi_config.sta.password, wifi_password,
           strnlen(wifi_password, sizeof(wifi_config.sta.password)));
    wifi_config.sta.threshold.authmode = wifi_password[0] == '\0' ? WIFI_AUTH_OPEN : WIFI_AUTH_WPA2_PSK;
    wifi_config.sta.pmf_cfg.capable = true;
    wifi_config.sta.pmf_cfg.required = false;

    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_STA));
    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_STA, &wifi_config));
    ESP_ERROR_CHECK(esp_wifi_start());

    ESP_LOGI(TAG, "Wi-Fi initialized; connection continues in the background");
}

