static void set_label_text_if_changed(lv_obj_t *label, const char *text)
{
    if (label && strcmp(lv_label_get_text(label), text) != 0) {
        lv_label_set_text(label, text);
    }
}

static const char *weekday_ru(int wday)
{
    static const char *const names[] = {"Вс", "Пн", "Вт", "Ср", "Чт", "Пт", "Сб"};
    return wday >= 0 && wday < 7 ? names[wday] : "";
}

static bool wifi_is_connected(void)
{
    return wifi_event_group &&
           (xEventGroupGetBits(wifi_event_group) & WIFI_CONNECTED_BIT) != 0;
}

static bool wifi_get_rssi(int8_t *rssi)
{
    if (!rssi || !wifi_is_connected()) return false;

    wifi_ap_record_t ap_info;
    if (esp_wifi_sta_get_ap_info(&ap_info) != ESP_OK) return false;
    *rssi = ap_info.rssi;
    return true;
}

static void update_display(void)
{
    if (wifi_setup_mode) {
        set_label_text_if_changed(label_time, "Wi-Fi");
        set_label_text_if_changed(label_date, "Connecting the clock to Wi-Fi");
        set_label_text_if_changed(label_city, "192.168.4.1");
        set_label_text_if_changed(label_wifi, "--");
        lv_obj_set_style_text_color(label_wifi, lv_color_hex(0x888888), 0);
        lv_image_set_src(icon_wifi, &wifi_disconnected_icon);
        lv_obj_set_style_image_recolor(icon_wifi, lv_color_hex(0x888888), 0);
        lv_display_t *disp = lv_display_get_default();
        if (disp) lv_refr_now(disp);
        return;
    }

    struct tm timeinfo;
    bool time_ok = false;

    /* The system epoch is the source of truth: it follows the selected TZ. */
    time_t now;
    time(&now);
    localtime_r(&now, &timeinfo);
    if (timeinfo.tm_year + 1900 >= 2024) {
        time_ok = true;
    }

    /* Use the RTC only when the system clock has not been initialized yet. */
    if (!time_ok && rtc_available) {
        if (ds3231_read_time(&timeinfo) && timeinfo.tm_year + 1900 >= 2024) {
            time_ok = true;
        }
    }

    char time_buf[32] = {0};
    char date_buf[32] = {0};

    if (time_ok) {
        strftime(time_buf, sizeof(time_buf), "%H:%M:%S", &timeinfo);
        snprintf(date_buf, sizeof(date_buf), "%s, %02d.%02d.%04d",
                 weekday_ru(timeinfo.tm_wday), timeinfo.tm_mday,
                 timeinfo.tm_mon + 1, timeinfo.tm_year + 1900);
    } else {
        snprintf(time_buf, sizeof(time_buf), "--:--:--");
        snprintf(date_buf, sizeof(date_buf), "Ожидание...");
    }

    set_label_text_if_changed(label_date, date_buf);
    set_label_text_if_changed(label_time, time_buf);

    char country_display[CITY_COUNTRY_MAX_LEN] = {0};
    country_for_display(cities[current_city_index].country,
                        country_display, sizeof(country_display));

    char city_country[CITY_NAME_MAX_LEN + CITY_COUNTRY_MAX_LEN + 3];
    snprintf(city_country, sizeof(city_country), "%s, %s",
             cities[current_city_index].city,
             country_display);
    set_label_text_if_changed(label_city, city_country);

    const bool wifi_connected = wifi_is_connected();
    int8_t rssi = 0;
    const bool rssi_valid = wifi_get_rssi(&rssi);
    char wifi_buf[8];
    if (rssi_valid) {
        snprintf(wifi_buf, sizeof(wifi_buf), "%d", rssi);
    } else {
        strlcpy(wifi_buf, "--", sizeof(wifi_buf));
    }
    set_label_text_if_changed(label_wifi, wifi_buf);
    lv_obj_set_style_text_color(label_wifi,
                                lv_color_hex(wifi_connected ? 0x00FFCC : 0x888888), 0);

    static int displayed_wifi_state = -1;
    if (displayed_wifi_state != wifi_connected) {
        displayed_wifi_state = wifi_connected;
        lv_image_set_src(icon_wifi, wifi_connected ? &wifi_connected_icon : &wifi_disconnected_icon);
        lv_obj_set_style_image_recolor(icon_wifi,
                                       lv_color_hex(wifi_connected ? 0x00FFCC : 0x888888), 0);
    }

    lv_display_t *disp = lv_display_get_default();
    if (disp) lv_refr_now(disp);
}

