static esp_err_t root_get_handler(httpd_req_t *req)
{
    httpd_resp_set_type(req, "text/html; charset=utf-8");
    httpd_resp_set_hdr(req, "Cache-Control", "no-store, no-cache, must-revalidate");
    httpd_resp_send(req, wifi_setup_mode ? WIFI_SETUP_PAGE : HTML_PAGE, HTTPD_RESP_USE_STRLEN);
    return ESP_OK;
}

static esp_err_t captive_portal_get_handler(httpd_req_t *req)
{
    if (wifi_setup_mode) return root_get_handler(req);
    httpd_resp_send_err(req, HTTPD_404_NOT_FOUND, "Not found");
    return ESP_FAIL;
}

static esp_err_t wifi_networks_get_handler(httpd_req_t *req)
{
    wifi_ap_record_t records[20];
    uint16_t count = sizeof(records) / sizeof(records[0]);
    memset(records, 0, sizeof(records));
    if (esp_wifi_scan_start(NULL, true) != ESP_OK ||
        esp_wifi_scan_get_ap_records(&count, records) != ESP_OK) {
        httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "Wi-Fi scan failed");
        return ESP_FAIL;
    }

    char *json = malloc(6144);
    if (!json) {
        httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "Out of memory");
        return ESP_FAIL;
    }
    size_t used = 0;
    json[used++] = '[';
    for (uint16_t i = 0; i < count && used + 220 < 6144; i++) {
        if (records[i].ssid[0] == '\0') continue;
        if (used > 1) json[used++] = ',';
        json[used++] = '"';
        for (size_t j = 0; j < sizeof(records[i].ssid) && records[i].ssid[j]; j++) {
            const unsigned char c = records[i].ssid[j];
            if (c < 0x20) continue;
            if ((c == '"' || c == '\\') && used + 2 < 6144) json[used++] = '\\';
            if (used + 2 < 6144) json[used++] = (char)c;
        }
        json[used++] = '"';
    }
    json[used++] = ']';
    json[used] = '\0';
    httpd_resp_set_type(req, "application/json; charset=utf-8");
    httpd_resp_set_hdr(req, "Cache-Control", "no-store");
    httpd_resp_send(req, json, (ssize_t)used);
    free(json);
    return ESP_OK;
}

static esp_err_t status_get_handler(httpd_req_t *req)
{
    int8_t rssi = 0;
    const bool rssi_valid = wifi_get_rssi(&rssi);
    char buf[192];
    snprintf(buf, sizeof(buf),
             "{\"wifi\":%s,\"rssi_valid\":%s,\"rssi\":%d,\"rtc\":%s,\"ntp\":%s,\"heap\":%lu}",
             wifi_is_connected() ? "true" : "false",
             rssi_valid ? "true" : "false", rssi,
             rtc_available ? "true" : "false",
             ntp_synced ? "true" : "false",
             (unsigned long)esp_get_free_heap_size());
    httpd_resp_set_type(req, "application/json; charset=utf-8");
    httpd_resp_set_hdr(req, "Cache-Control", "no-store");
    httpd_resp_send(req, buf, HTTPD_RESP_USE_STRLEN);
    return ESP_OK;
}

static esp_err_t cities_get_handler(httpd_req_t *req)
{
    ESP_LOGI(TAG, "GET /cities started");
    char query[128] = {0};
    char search[96] = {0};
    if (httpd_req_get_url_query_str(req, query, sizeof(query)) == ESP_OK) {
        form_get_value(query, "q", search, sizeof(search));
    }

    char *buf = calloc(1, 12288);
    city_db_record_t *matches = NULL;
    uint32_t *match_indexes = NULL;
    if (search[0] != '\0') {
        matches = calloc(30, sizeof(city_db_record_t));
        match_indexes = calloc(30, sizeof(uint32_t));
    }
    if (!buf || (search[0] != '\0' && (!matches || !match_indexes))) {
        ESP_LOGE(TAG, "Cities HTTP request out of memory (search=%s, free=%lu, largest=%lu)",
                 search[0] != '\0' ? "yes" : "no",
                 (unsigned long)esp_get_free_heap_size(),
                 (unsigned long)heap_caps_get_largest_free_block(MALLOC_CAP_8BIT));
        free(buf);
        free(matches);
        free(match_indexes);
        httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "Out of memory");
        return ESP_FAIL;
    }

    int used = snprintf(buf, 12288, "{\"current\":%u,\"cities\":[", current_city_index);
    for (size_t i = 0; i < CITY_COUNT && used < 12288; i++) {
        used += snprintf(buf + used, 12288 - (size_t)used,
                         "%s{\"index\":%u,\"city\":\"%s\",\"country\":\"%s\",\"tz\":\"%s\",\"custom\":%s}",
                         i == 0 ? "" : ",", (unsigned)i,
                         cities[i].city, cities[i].country, cities[i].tz_string,
                         i >= DEFAULT_CITY_COUNT ? "true" : "false");
    }

    uint32_t found = city_database_search(search, 30, matches, match_indexes);
    ESP_LOGI(TAG, "GET /cities search='%s' found=%lu", search, (unsigned long)found);
    if (used < 12288) used += snprintf(buf + used, 12288 - (size_t)used, "],\"results\":[");
    for (uint32_t i = 0; i < found && used < 12288; i++) {
        used += snprintf(buf + used, 12288 - (size_t)used,
                         "%s{\"db\":%lu,\"city\":\"%s\",\"country\":\"%s\",\"tz\":\"%s\"}",
                         i == 0 ? "" : ",", (unsigned long)match_indexes[i],
                         matches[i].name, matches[i].country, matches[i].timezone);
    }
    if (used < 12288) snprintf(buf + used, 12288 - (size_t)used, "]}");

    ESP_LOGI(TAG, "GET /cities response=%d bytes", used);
    httpd_resp_set_type(req, "application/json; charset=utf-8");
    httpd_resp_send(req, buf, HTTPD_RESP_USE_STRLEN);
    free(buf);
    free(matches);
    free(match_indexes);
    return ESP_OK;
}

static esp_err_t city_post_handler(httpd_req_t *req)
{
    char content[48];
    size_t recv_size = req->content_len;
    if (recv_size == 0 || recv_size >= sizeof(content)) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid city index");
        return ESP_FAIL;
    }

    int ret = httpd_req_recv(req, content, recv_size);
    if (ret <= 0) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid city index");
        return ESP_FAIL;
    }
    content[ret] = '\0';

    char value[32];
    if (form_get_value(content, "db", value, sizeof(value))) {
        uint32_t db_index = (uint32_t)strtoul(value, NULL, 10);
        city_db_record_t record;
        if (!city_database_get(db_index, &record)) {
            httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Unknown database city");
            return ESP_FAIL;
        }

        int existing = -1;
        for (uint8_t i = 0; i < city_count; i++) {
            if (strcmp(cities[i].city, record.name) == 0 &&
                strcmp(cities[i].tz_string, record.timezone) == 0) {
                existing = i;
                break;
            }
        }
        if (existing < 0) {
            if (city_count >= MAX_CITIES) {
                httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "User city list is full");
                return ESP_FAIL;
            }
            city_t item = {0};
            strlcpy(item.city, record.name, sizeof(item.city));
            strlcpy(item.country, record.country, sizeof(item.country));
            strlcpy(item.tz_string, record.timezone, sizeof(item.tz_string));
            cities[city_count] = item;
            existing = city_count++;
        }
        current_city_index = (uint8_t)existing;
        city_state_save_pending = true;
        need_tz_update = true;

        char response[512];
        snprintf(response, sizeof(response),
                 "{\"current\":%u,\"city\":\"%s\",\"country\":\"%s\",\"tz\":\"%s\"}",
                 (unsigned)existing, cities[existing].city,
                 cities[existing].country, cities[existing].tz_string);
        httpd_resp_set_type(req, "application/json; charset=utf-8");
        httpd_resp_send(req, response, HTTPD_RESP_USE_STRLEN);
        return ESP_OK;
    }

    int index = -1;
    if (form_get_value(content, "index", value, sizeof(value))) {
        index = atoi(value);
    } else {
        index = atoi(content);
    }
    if (index < 0 || index >= (int)CITY_COUNT) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Unknown city");
        return ESP_FAIL;
    }

    current_city_index = (uint8_t)index;
    city_state_save_pending = true;
    need_tz_update = true;

    char response[512];
    snprintf(response, sizeof(response),
             "{\"current\":%u,\"city\":\"%s\",\"country\":\"%s\",\"tz\":\"%s\"}",
             (unsigned)index, cities[index].city, cities[index].country,
             cities[index].tz_string);

    httpd_resp_set_type(req, "application/json; charset=utf-8");
    httpd_resp_send(req, response, HTTPD_RESP_USE_STRLEN);
    return ESP_OK;
}

static int hex_value(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static void url_decode(char *dst, size_t dst_size, const char *src)
{
    if (dst_size == 0) return;
    size_t out = 0;
    while (*src && out + 1 < dst_size) {
        if (*src == '+') {
            dst[out++] = ' ';
            src++;
        } else if (*src == '%' && src[1] && src[2]) {
            int hi = hex_value(src[1]);
            int lo = hex_value(src[2]);
            if (hi >= 0 && lo >= 0) {
                dst[out++] = (char)((hi << 4) | lo);
                src += 3;
            } else {
                dst[out++] = *src++;
            }
        } else {
            dst[out++] = *src++;
        }
    }
    dst[out] = '\0';
}

static bool form_get_value(const char *body, const char *key, char *out, size_t out_size)
{
    if (out_size == 0) return false;
    char needle[32];
    snprintf(needle, sizeof(needle), "%s=", key);
    const char *p = body;
    while ((p = strstr(p, needle)) != NULL) {
        if (p == body || p[-1] == '&') {
            p += strlen(needle);
            const char *end = strchr(p, '&');
            size_t length = end ? (size_t)(end - p) : strlen(p);
            if (length >= out_size) length = out_size - 1;
            char encoded[256];
            if (length >= sizeof(encoded)) length = sizeof(encoded) - 1;
            memcpy(encoded, p, length);
            encoded[length] = '\0';
            url_decode(out, out_size, encoded);
            return true;
        }
        p += strlen(needle);
    }
    out[0] = '\0';
    return false;
}

static int receive_request_body(httpd_req_t *req, char *buffer, size_t buffer_size)
{
    if (req->content_len == 0 || req->content_len >= buffer_size) return -1;
    size_t received = 0;
    while (received < req->content_len) {
        int ret = httpd_req_recv(req, buffer + received, req->content_len - received);
        if (ret <= 0) return -1;
        received += (size_t)ret;
    }
    buffer[received] = '\0';
    return (int)received;
}

static void delayed_restart_task(void *arg)
{
    (void)arg;
    vTaskDelay(pdMS_TO_TICKS(1500));
    esp_restart();
}

static esp_err_t wifi_post_handler(httpd_req_t *req)
{
    char content[512];
    char ssid[sizeof(wifi_ssid)] = {0};
    char password[sizeof(wifi_password)] = {0};
    if (receive_request_body(req, content, sizeof(content)) <= 0 ||
        !form_get_value(content, "ssid", ssid, sizeof(ssid)) || ssid[0] == '\0' ||
        !form_get_value(content, "password", password, sizeof(password))) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Введите название Wi-Fi");
        return ESP_FAIL;
    }

    nvs_handle_t handle = 0;
    esp_err_t err = nvs_open("clock", NVS_READWRITE, &handle);
    if (err == ESP_OK) err = nvs_set_str(handle, "wifi_ssid", ssid);
    if (err == ESP_OK) err = nvs_set_str(handle, "wifi_password", password);
    if (err == ESP_OK) err = nvs_commit(handle);
    if (handle) nvs_close(handle);
    if (err != ESP_OK) {
        httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "Не удалось сохранить настройки");
        return ESP_FAIL;
    }

    if (xTaskCreate(delayed_restart_task, "wifi_restart", 2048, NULL, 5, NULL) != pdPASS) {
        httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "Перезапустите часы кнопкой питания");
        return ESP_FAIL;
    }
    httpd_resp_set_type(req, "text/html; charset=utf-8");
    httpd_resp_send(req,
        "<meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'>"
        "<body style='font:22px Arial;max-width:560px;margin:40px auto;padding:20px'>"
        "<h1>Готово!</h1><p>Часы перезапускаются и подключаются к домашнему Wi-Fi. "
        "Теперь телефон можно подключить обратно к домашней сети.</p></body>",
        HTTPD_RESP_USE_STRLEN);
    return ESP_OK;
}

static esp_err_t city_add_post_handler(httpd_req_t *req)
{
    char content[256];
    if (receive_request_body(req, content, sizeof(content)) <= 0) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid city data");
        return ESP_FAIL;
    }
    if (city_count >= MAX_CITIES) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "City list is full");
        return ESP_FAIL;
    }

    city_t item = {0};
    if (!form_get_value(content, "city", item.city, sizeof(item.city)) ||
        !form_get_value(content, "country", item.country, sizeof(item.country)) ||
        !form_get_value(content, "tz", item.tz_string, sizeof(item.tz_string)) ||
        item.city[0] == '\0' || item.country[0] == '\0' || item.tz_string[0] == '\0') {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "City, country and timezone are required");
        return ESP_FAIL;
    }

    cities[city_count++] = item;
    save_custom_cities();
    ESP_LOGI(TAG, "City added: %s, %s, TZ=%s", item.city, item.country, item.tz_string);

    httpd_resp_set_type(req, "text/plain; charset=utf-8");
    httpd_resp_send(req, "City added", HTTPD_RESP_USE_STRLEN);
    return ESP_OK;
}

static esp_err_t city_delete_handler(httpd_req_t *req)
{
    char query[64];
    char value[16];
    int index = -1;
    if (httpd_req_get_url_query_str(req, query, sizeof(query)) == ESP_OK &&
        form_get_value(query, "index", value, sizeof(value))) {
        index = atoi(value);
    }
    if (index < (int)DEFAULT_CITY_COUNT || index >= (int)city_count) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Built-in cities cannot be deleted");
        return ESP_FAIL;
    }

    for (int i = index; i < city_count - 1; i++) cities[i] = cities[i + 1];
    city_count--;
    if (current_city_index == index) {
        current_city_index = 0;
        need_tz_update = true;
        save_current_city();
    } else if (current_city_index > index) {
        current_city_index--;
        save_current_city();
    }
    save_custom_cities();

    httpd_resp_set_type(req, "text/plain; charset=utf-8");
    httpd_resp_send(req, "City deleted", HTTPD_RESP_USE_STRLEN);
    return ESP_OK;
}

static esp_err_t ntp_get_handler(httpd_req_t *req)
{
    char *buf = calloc(1, 8192);
    if (buf == NULL) {
        httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "Out of memory");
        return ESP_FAIL;
    }

    int used = snprintf(buf, 8192,
                        "{\"timeout\":%u,\"interval\":%u,\"servers\":[",
                        (unsigned)ntp_timeout_ms, (unsigned)sync_interval_sec);
    for (uint8_t i = 0; i < ntp_cfg_count && used < 8192; i++) {
        used += snprintf(buf + used, 8192 - (size_t)used,
                         "%s{\"index\":%u,\"host\":\"%s\",\"enabled\":%s}",
                         i == 0 ? "" : ",", (unsigned)i, ntp_cfg[i].host,
                         ntp_cfg[i].enabled ? "true" : "false");
    }
    if (used < 8192) snprintf(buf + used, 8192 - (size_t)used, "]}");

    httpd_resp_set_type(req, "application/json; charset=utf-8");
    httpd_resp_send(req, buf, HTTPD_RESP_USE_STRLEN);
    free(buf);
    return ESP_OK;
}

static esp_err_t ntp_post_handler(httpd_req_t *req)
{
    char *content = calloc(1, 8192);
    if (content == NULL) {
        httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "Out of memory");
        return ESP_FAIL;
    }

    size_t recv_size = req->content_len;
    if (recv_size == 0 || recv_size >= 8192) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "NTP configuration too long");
        free(content);
        return ESP_FAIL;
    }
    int ret = receive_request_body(req, content, 8192);
    if (ret <= 0) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid NTP configuration");
        free(content);
        return ESP_FAIL;
    }

    char value[128];
    int count = MAX_NTP_SERVERS;
    if (form_get_value(content, "count", value, sizeof(value))) count = atoi(value);
    if (count < 1 || count > MAX_NTP_SERVERS) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid NTP server count");
        free(content);
        return ESP_FAIL;
    }

    uint32_t timeout = ntp_timeout_ms;
    uint32_t interval = sync_interval_sec;
    if (form_get_value(content, "timeout", value, sizeof(value))) timeout = (uint32_t)strtoul(value, NULL, 10);
    if (form_get_value(content, "interval", value, sizeof(value))) interval = (uint32_t)strtoul(value, NULL, 10);
    if (timeout < 1000 || timeout > 120000 || interval < 60 || interval > 7U * 24U * 3600U) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid NTP timeout or interval");
        free(content);
        return ESP_FAIL;
    }

    ntp_server_config_t new_cfg[MAX_NTP_SERVERS] = {0};
    for (uint8_t i = 0; i < (uint8_t)count; i++) {
        char key[24];
        snprintf(key, sizeof(key), "host%u", (unsigned)i);
        if (!form_get_value(content, key, new_cfg[i].host, sizeof(new_cfg[i].host)) ||
            new_cfg[i].host[0] == '\0') {
            httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "NTP host cannot be empty");
            free(content);
            return ESP_FAIL;
        }
        snprintf(key, sizeof(key), "enabled%u", (unsigned)i);
        new_cfg[i].enabled = form_get_value(content, key, value, sizeof(value)) && atoi(value) != 0;
    }

    // Commit only after the complete request has been validated.
    memcpy(ntp_cfg, new_cfg, sizeof(new_cfg));
    ntp_cfg_count = (uint8_t)count;
    ntp_timeout_ms = timeout;
    sync_interval_sec = interval;
    save_ntp_config();
    if (last_sync_epoch > 0) next_sync_epoch = last_sync_epoch + (time_t)sync_interval_sec;
    if (!ntp_sync_running) start_background_ntp();
    ESP_LOGI(TAG, "NTP configuration saved: %u server(s), timeout=%u ms, interval=%u s",
             (unsigned)ntp_cfg_count, (unsigned)ntp_timeout_ms, (unsigned)sync_interval_sec);

    httpd_resp_set_type(req, "text/plain; charset=utf-8");
    httpd_resp_send(req, "NTP settings saved", HTTPD_RESP_USE_STRLEN);
    free(content);
    return ESP_OK;
}

static esp_err_t alarms_get_handler(httpd_req_t *req)
{
    char buf[4096];
    int used = snprintf(buf, sizeof(buf), "{\"alarms\":[");
    for (uint8_t i = 0; i < alarm_count && used < (int)sizeof(buf); i++) {
        used += snprintf(buf + used, sizeof(buf) - (size_t)used,
                         "%s{\"index\":%u,\"hour\":%u,\"minute\":%u,\"days\":%u,\"enabled\":%s,\"label\":\"%s\"}",
                         i == 0 ? "" : ",", (unsigned)i,
                         (unsigned)alarms[i].hour, (unsigned)alarms[i].minute,
                         (unsigned)alarms[i].days_mask,
                         alarms[i].enabled ? "true" : "false", alarms[i].label);
    }
    if (used < (int)sizeof(buf)) snprintf(buf + used, sizeof(buf) - (size_t)used, "]}");

    httpd_resp_set_type(req, "application/json; charset=utf-8");
    httpd_resp_send(req, buf, HTTPD_RESP_USE_STRLEN);
    return ESP_OK;
}

static esp_err_t alarm_post_handler(httpd_req_t *req)
{
    char content[512];
    size_t recv_size = req->content_len;
    if (recv_size == 0 || recv_size >= sizeof(content)) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Alarm data too long");
        return ESP_FAIL;
    }
    int ret = receive_request_body(req, content, sizeof(content));
    if (ret <= 0) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid alarm data");
        return ESP_FAIL;
    }

    char value[128];
    int index = -1;
    int hour = 0;
    int minute = 0;
    int days = 0;
    bool enabled = true;
    char label[ALARM_LABEL_MAX_LEN] = "Будильник";

    if (form_get_value(content, "index", value, sizeof(value))) index = atoi(value);
    if (form_get_value(content, "hour", value, sizeof(value))) hour = atoi(value);
    if (form_get_value(content, "minute", value, sizeof(value))) minute = atoi(value);
    if (form_get_value(content, "days", value, sizeof(value))) days = atoi(value);
    if (form_get_value(content, "enabled", value, sizeof(value))) enabled = atoi(value) != 0;
    form_get_value(content, "label", label, sizeof(label));
    if (label[0] == '\0') strlcpy(label, "Будильник", sizeof(label));

    if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || days < 1 || days > 127) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid alarm time or days");
        return ESP_FAIL;
    }
    if (index < 0) {
        if (alarm_count >= MAX_ALARMS) {
            httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Alarm limit reached");
            return ESP_FAIL;
        }
        index = alarm_count++;
    }
    if (index >= alarm_count || index >= MAX_ALARMS) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid alarm index");
        return ESP_FAIL;
    }

    alarms[index].hour = (uint8_t)hour;
    alarms[index].minute = (uint8_t)minute;
    alarms[index].days_mask = (uint8_t)days;
    alarms[index].enabled = enabled;
    strlcpy(alarms[index].label, label, sizeof(alarms[index].label));
    alarm_last_key[index] = -1;
    save_alarms();
    ESP_LOGI(TAG, "Alarm saved: index=%d %02d:%02d days=0x%02X enabled=%d label=%s",
             index, hour, minute, (unsigned)days, enabled ? 1 : 0, alarms[index].label);

    httpd_resp_set_type(req, "text/plain; charset=utf-8");
    httpd_resp_send(req, "Alarm saved", HTTPD_RESP_USE_STRLEN);
    return ESP_OK;
}

static esp_err_t alarm_delete_handler(httpd_req_t *req)
{
    char query[64];
    char value[16];
    int index = -1;
    if (httpd_req_get_url_query_str(req, query, sizeof(query)) == ESP_OK &&
        form_get_value(query, "index", value, sizeof(value))) {
        index = atoi(value);
    }
    if (index < 0 || index >= alarm_count) {
        httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid alarm index");
        return ESP_FAIL;
    }

    for (int i = index; i < alarm_count - 1; i++) {
        alarms[i] = alarms[i + 1];
        alarm_last_key[i] = alarm_last_key[i + 1];
    }
    memset(&alarms[alarm_count - 1], 0, sizeof(alarms[0]));
    alarm_last_key[alarm_count - 1] = -1;
    alarm_count--;
    save_alarms();

    httpd_resp_set_type(req, "text/plain; charset=utf-8");
    httpd_resp_send(req, "Alarm deleted", HTTPD_RESP_USE_STRLEN);
    return ESP_OK;
}

